Save the following as `index.html` and open it in a modern browser. It uses only the Three.js core ES module from cdnjs; camera orbit and zoom controls are implemented directly.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Wooden Windmill</title>

  <style>
    * {
      box-sizing: border-box;
    }

    html,
    body {
      width: 100%;
      height: 100%;
      margin: 0;
      overflow: hidden;
      background: #b9d9e8;
    }

    body {
      font-family: Georgia, "Times New Roman", serif;
    }

    canvas {
      display: block;
      width: 100%;
      height: 100%;
      touch-action: none;
      cursor: grab;
    }

    canvas:active {
      cursor: grabbing;
    }

    .title {
      position: fixed;
      top: 22px;
      left: 26px;
      z-index: 2;
      color: #312a24;
      pointer-events: none;
      text-shadow: 0 1px 12px rgba(255, 255, 255, 0.65);
    }

    .title h1 {
      margin: 0;
      font-size: clamp(24px, 4vw, 42px);
      font-weight: 600;
      letter-spacing: 0.025em;
    }

    .title p {
      margin: 5px 0 0;
      font-family: Arial, Helvetica, sans-serif;
      font-size: 12px;
      letter-spacing: 0.18em;
      text-transform: uppercase;
      opacity: 0.72;
    }

    .hint {
      position: fixed;
      right: 20px;
      bottom: 18px;
      z-index: 2;
      padding: 9px 13px;
      border: 1px solid rgba(255, 255, 255, 0.35);
      border-radius: 999px;
      color: #312a24;
      background: rgba(255, 255, 255, 0.52);
      backdrop-filter: blur(8px);
      font: 12px Arial, Helvetica, sans-serif;
      pointer-events: none;
    }

    @media (max-width: 600px) {
      .title {
        top: 16px;
        left: 18px;
      }

      .hint {
        right: 12px;
        bottom: 12px;
      }
    }
  </style>
</head>

<body>
  <div class="title">
    <h1>The Windmill</h1>
    <p>Procedural Three.js Scene</p>
  </div>

  <div class="hint">Drag to orbit · Scroll to zoom · Double-click to reset</div>

  <script type="module">
    import * as THREE from
      "https://cdnjs.cloudflare.com/ajax/libs/three.js/0.160.0/three.module.min.js";

    // -------------------------------------------------------------------------
    // Renderer, scene, and camera
    // -------------------------------------------------------------------------

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0xb9d9e8);
    scene.fog = new THREE.Fog(0xb9d9e8, 26, 68);

    const camera = new THREE.PerspectiveCamera(
      42,
      innerWidth / innerHeight,
      0.1,
      100
    );

    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      powerPreference: "high-performance"
    });

    renderer.setSize(innerWidth, innerHeight);
    renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.05;
    document.body.appendChild(renderer.domElement);

    // -------------------------------------------------------------------------
    // Procedural textures
    // -------------------------------------------------------------------------

    function seededRandom(seed) {
      let value = seed >>> 0;
      return function () {
        value = (value * 1664525 + 1013904223) >>> 0;
        return value / 4294967296;
      };
    }

    function createWoodTexture() {
      const canvas = document.createElement("canvas");
      canvas.width = canvas.height = 256;
      const ctx = canvas.getContext("2d");
      const random = seededRandom(8127);

      ctx.fillStyle = "#b9824e";
      ctx.fillRect(0, 0, 256, 256);

      for (let i = 0; i < 110; i++) {
        const y = random() * 256;
        const amplitude = 1 + random() * 5;
        const frequency = 0.025 + random() * 0.065;

        ctx.beginPath();
        for (let x = 0; x <= 256; x += 4) {
          const wave = Math.sin(x * frequency + i) * amplitude;
          if (x === 0) ctx.moveTo(x, y + wave);
          else ctx.lineTo(x, y + wave);
        }

        ctx.strokeStyle = `rgba(74, 37, 15, ${0.035 + random() * 0.11})`;
        ctx.lineWidth = 0.5 + random() * 1.7;
        ctx.stroke();
      }

      for (let i = 0; i < 8; i++) {
        const x = random() * 256;
        const y = random() * 256;
        const radius = 7 + random() * 18;

        ctx.beginPath();
        ctx.ellipse(x, y, radius, radius * 0.35, random() * 0.4, 0, Math.PI * 2);
        ctx.strokeStyle = "rgba(73, 35, 15, 0.16)";
        ctx.lineWidth = 1.2;
        ctx.stroke();
      }

      const texture = new THREE.CanvasTexture(canvas);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
      texture.repeat.set(1.6, 1.6);
      texture.anisotropy = renderer.capabilities.getMaxAnisotropy();
      return texture;
    }

    function createGrassTexture() {
      const canvas = document.createElement("canvas");
      canvas.width = canvas.height = 256;
      const ctx = canvas.getContext("2d");
      const random = seededRandom(4411);

      ctx.fillStyle = "#66833b";
      ctx.fillRect(0, 0, 256, 256);

      for (let i = 0; i < 4200; i++) {
        const value = 70 + Math.floor(random() * 75);
        const green = Math.floor(value * 1.15);
        const red = Math.floor(value * 0.62);
        const blue = Math.floor(value * 0.25);

        ctx.fillStyle = `rgb(${red}, ${green}, ${blue})`;
        const size = 1 + random() * 3;
        ctx.fillRect(random() * 256, random() * 256, size, size * 2.4);
      }

      const texture = new THREE.CanvasTexture(canvas);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
      texture.repeat.set(7, 7);
      texture.anisotropy = renderer.capabilities.getMaxAnisotropy();
      return texture;
    }

    const woodTexture = createWoodTexture();
    const grassTexture = createGrassTexture();

    const materials = {
      wood: new THREE.MeshStandardMaterial({
        map: woodTexture,
        color: 0xffffff,
        roughness: 0.86,
        metalness: 0
      }),
      darkWood: new THREE.MeshStandardMaterial({
        map: woodTexture,
        color: 0x806044,
        roughness: 0.9
      }),
      metal: new THREE.MeshStandardMaterial({
        color: 0x293038,
        roughness: 0.48,
        metalness: 0.65
      }),
      glass: new THREE.MeshStandardMaterial({
        color: 0x244753,
        roughness: 0.24,
        metalness: 0.18,
        emissive: 0x08171d,
        emissiveIntensity: 0.25
      }),
      stone: new THREE.MeshStandardMaterial({
        color: 0x777b73,
        roughness: 0.98
      }),
      ground: new THREE.MeshStandardMaterial({
        color: 0x6f8247,
        roughness: 1
      }),
      grass: new THREE.MeshStandardMaterial({
        map: grassTexture,
        color: 0xffffff,
        roughness: 1
      })
    };

    // -------------------------------------------------------------------------
    // Lighting
    // -------------------------------------------------------------------------

    const hemisphere = new THREE.HemisphereLight(0xd9efff, 0x665b37, 2.1);
    scene.add(hemisphere);

    const sun = new THREE.DirectionalLight(0xfff0cf, 3.2);
    sun.position.set(11, 18, 12);
    sun.castShadow = true;
    sun.shadow.mapSize.set(2048, 2048);
    sun.shadow.camera.left = -14;
    sun.shadow.camera.right = 14;
    sun.shadow.camera.top = 18;
    sun.shadow.camera.bottom = -8;
    sun.shadow.camera.near = 1;
    sun.shadow.camera.far = 45;
    sun.shadow.normalBias = 0.025;
    scene.add(sun);

    const fill = new THREE.DirectionalLight(0x9ec9df, 0.65);
    fill.position.set(-10, 8, -12);
    scene.add(fill);

    // -------------------------------------------------------------------------
    // Geometry helpers
    // -------------------------------------------------------------------------

    const Y_AXIS = new THREE.Vector3(0, 1, 0);

    function addBox(
      width,
      height,
      depth,
      material,
      x,
      y,
      z,
      parent = scene
    ) {
      const mesh = new THREE.Mesh(
        new THREE.BoxGeometry(width, height, depth),
        material
      );
      mesh.position.set(x, y, z);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);
      return mesh;
    }

    function beamBetween(
      start,
      end,
      thickness,
      material,
      parent = scene
    ) {
      const a = start.isVector3 ? start : new THREE.Vector3(...start);
      const b = end.isVector3 ? end : new THREE.Vector3(...end);
      const direction = b.clone().sub(a);
      const length = direction.length();

      const mesh = new THREE.Mesh(
        new THREE.BoxGeometry(thickness, length, thickness),
        material
      );

      mesh.position.copy(a).add(b).multiplyScalar(0.5);
      mesh.quaternion.setFromUnitVectors(
        Y_AXIS,
        direction.normalize()
      );
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);
      return mesh;
    }

    // -------------------------------------------------------------------------
    // Ground and grassy mound
    // -------------------------------------------------------------------------

    const ground = new THREE.Mesh(
      new THREE.PlaneGeometry(90, 90),
      materials.ground
    );
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -0.48;
    ground.receiveShadow = true;
    scene.add(ground);

    const mound = new THREE.Mesh(
      new THREE.SphereGeometry(
        4,
        48,
        24,
        0,
        Math.PI * 2,
        0,
        Math.PI / 2
      ),
      materials.grass
    );
    mound.position.y = -0.2;
    mound.scale.set(1.15, 0.5, 0.9);
    mound.receiveShadow = true;
    mound.castShadow = true;
    scene.add(mound);

    // Instanced grass tufts keep the scene lightweight.
    const tuftGeometry = new THREE.ConeGeometry(0.045, 0.34, 3);
    const tuftMaterial = new THREE.MeshStandardMaterial({
      color: 0x789347,
      roughness: 1
    });
    const tuftCount = 65;
    const tufts = new THREE.InstancedMesh(
      tuftGeometry,
      tuftMaterial,
      tuftCount
    );
    const dummy = new THREE.Object3D();
    const tuftRandom = seededRandom(991);

    for (let i = 0; i < tuftCount; i++) {
      const angle = tuftRandom() * Math.PI * 2;
      const radius = 2.5 + tuftRandom() * 1.55;
      const x = Math.cos(angle) * radius;
      const z = Math.sin(angle) * radius * 0.9;

      dummy.position.set(x, 0.03 + tuftRandom() * 0.04, z);
      dummy.rotation.set(
        (tuftRandom() - 0.5) * 0.2,
        tuftRandom() * Math.PI,
        (tuftRandom() - 0.5) * 0.2
      );
      dummy.scale.setScalar(0.65 + tuftRandom() * 1.2);
      dummy.updateMatrix();
      tufts.setMatrixAt(i, dummy.matrix);
    }

    tufts.castShadow = true;
    scene.add(tufts);

    // -------------------------------------------------------------------------
    // Irregular stone foundation
    // -------------------------------------------------------------------------

    addBox(3.25, 0.3, 3.25, materials.stone, 0, 0.08, 0);

    const stoneGeometry = new THREE.DodecahedronGeometry(1, 0);
    const stoneRandom = seededRandom(723);

    for (let i = 0; i < 15; i++) {
      const angle = (i / 15) * Math.PI * 2 + stoneRandom() * 0.14;
      const radius = 2.25 + stoneRandom() * 0.25;
      const size = 0.48 + stoneRandom() * 0.35;

      const stone = new THREE.Mesh(stoneGeometry, materials.stone);
      stone.position.set(
        Math.cos(angle) * radius,
        0.25 + stoneRandom() * 0.15,
        Math.sin(angle) * radius
      );
      stone.scale.set(
        size * (0.8 + stoneRandom() * 0.4),
        size * (0.55 + stoneRandom() * 0.35),
        size * (0.8 + stoneRandom() * 0.4)
      );
      stone.rotation.set(
        stoneRandom() * Math.PI,
        stoneRandom() * Math.PI,
        stoneRandom() * Math.PI
      );
      stone.castShadow = true;
      stone.receiveShadow = true;
      scene.add(stone);
    }

    // -------------------------------------------------------------------------
    // Tapered wooden tower
    // -------------------------------------------------------------------------

    const towerBottom = 0.25;
    const towerTop = 6.85;
    const towerHeight = towerTop - towerBottom;
    const towerCenterY = (towerBottom + towerTop) / 2;

    const tower = new THREE.Mesh(
      new THREE.CylinderGeometry(1.55, 2.05, towerHeight, 4),
      materials.wood
    );
    tower.position.y = towerCenterY;
    tower.castShadow = true;
    tower.receiveShadow = true;
    scene.add(tower);

    function towerRadiusAt(y) {
      const t = THREE.MathUtils.clamp(
        (y - towerBottom) / towerHeight,
        0,
        1
      );
      return THREE.MathUtils.lerp(2.05, 1.55, t);
    }

    // Horizontal wooden bands around the tower.
    [0.55, 1.55, 2.55, 3.55, 4.55, 5.55, 6.55].forEach((y) => {
      const radius = towerRadiusAt(y);

      addBox(
        radius * 2,
        0.12,
        0.12,
        materials.darkWood,
        0,
        y,
        radius + 0.025
      );

      addBox(
        0.12,
        0.12,
        radius * 2,
        materials.darkWood,
        radius + 0.025,
        y,
        0
      );
    });

    // Tapered corner posts.
    const bottomCorners = [
      [0, 2.05],
      [2.05, 0],
      [0, -2.05],
      [-2.05, 0]
    ];

    bottomCorners.forEach(([x, z]) => {
      beamBetween(
        [x, towerBottom, z],
        [x * 0.76, towerTop, z * 0.76],
        0.13,
        materials.darkWood
      );
    });

    // Front diagonal braces.
    beamBetween(
      [0, 1.0, towerRadiusAt(1.0) + 0.05],
      [0, 2.15, towerRadiusAt(2.15) + 0.05],
      0.11,
      materials.darkWood
    );

    beamBetween(
      [0, 3.35, towerRadiusAt(3.35) + 0.05],
      [0, 4.5, towerRadiusAt(4.5) + 0.05],
      0.11,
      materials.darkWood
    );

    // -------------------------------------------------------------------------
    // Door and windows
    // -------------------------------------------------------------------------

    function addWindow(x, y, z, width, height) {
      const group = new THREE.Group();
      group.position.set(x, y, z);
      scene.add(group);

      addBox(
        0.08,
        height + 0.12,
        0.14,
        materials.darkWood,
        -width / 2,
        0,
        0,
        group
      );

      addBox(
        0.08,
        height + 0.12,
        0.14,
        materials.darkWood,
        width / 2,
        0,
        0,
        group
      );

      addBox(
        width + 0.12,
        0.08,
        0.14,
        materials.darkWood,
        0,
        height / 2,
        0,
        group
      );

      addBox(
        width + 0.12,
        0.08,
        0.14,
        materials.darkWood,
        0,
        -height / 2,
        0,
        group
      );

      addBox(
        width - 0.1,
        height - 0.1,
        0.055,
        materials.glass,
        0,
        0,
        0.025,
        group
      );

      addBox(
        0.065,
        height,
        0.1,
        materials.darkWood,
        0,
        0,
        0.075,
        group
      );

      addBox(
        width,
        0.065,
        0.1,
        materials.darkWood,
        0,
        0,
        0.075,
        group
      );
    }

    function addDoor(x, y, z) {
      const group = new THREE.Group();
      group.position.set(x, y, z);
      scene.add(group);

      addBox(
        0.78,
        1.48,
        0.1,
        materials.darkWood,
        0,
        0,
        0,
        group
      );

      for (let i = 0; i < 4; i++) {
        addBox(
          0.018,
          1.34,
          0.012,
          materials.wood,
          -0.25 + i * 0.187,
          0,
          0.061,
          group
        );
      }

      addBox(
        0.055,
        0.16,
        0.06,
        materials.metal,
        0.28,
        -0.38,
        0.12,
        group
      );

      addBox(
        0.1,
        0.1,
        0.04,
        materials.metal,
        0.28,
        -0.38,
        0.15,
        group
      );
    }

    addDoor(0, 2.12, towerRadiusAt(2.12) + 0.065);
    addWindow(-0.78, 4.08, towerRadiusAt(4.08) + 0.065, 0.64, 0.82);
    addWindow(0.78, 4.08, towerRadiusAt(4.08) + 0.065, 0.64, 0.82);

    // -------------------------------------------------------------------------
    // Conical roof and finial
    // -------------------------------------------------------------------------

    const roofTrim = new THREE.Mesh(
      new THREE.CylinderGeometry(1.98, 1.98, 0.18, 4),
      materials.darkWood
    );
    roofTrim.position.y = 6.96;
    roofTrim.rotation.y = Math.PI / 4;
    roofTrim.castShadow = true;
    scene.add(roofTrim);

    const roof = new THREE.Mesh(
      new THREE.ConeGeometry(2.02, 1.4, 4),
      materials.wood
    );
    roof.position.y = 7.64;
    roof.rotation.y = Math.PI / 4;
    roof.castShadow = true;
    roof.receiveShadow = true;
    scene.add(roof);

    const finial = new THREE.Mesh(
      new THREE.SphereGeometry(0.13, 12, 8),
      materials.metal
    );
    finial.position.y = 8.42;
    finial.castShadow = true;
    scene.add(finial);

    beamBetween(
      [0, 7.95, 0],
      [0, 8.42, 0],
      0.055,
      materials.metal
    );

    // -------------------------------------------------------------------------
    // Horizontal shaft and four rotating lattice sails
    // -------------------------------------------------------------------------

    const rotatingAssembly = new THREE.Group();
    scene.add(rotatingAssembly);

    const shaft = new THREE.Mesh(
      new THREE.CylinderGeometry(0.15, 0.15, 9.4, 18),
      materials.metal
    );
    shaft.rotation.z = Math.PI / 2;
    shaft.position.y = 6;
    shaft.castShadow = true;
    rotatingAssembly.add(shaft);

    const sailPositions = [-2.75, -0.92, 0.92, 2.75];

    sailPositions.forEach((x, index) => {
      // Collar around the shaft.
      const collar = new THREE.Mesh(
        new THREE.TorusGeometry(0.22, 0.055, 8, 18),
        materials.darkWood
      );
      collar.rotation.y = Math.PI / 2;
      collar.position.set(x, 6, 0);
      collar.castShadow = true;
      rotatingAssembly.add(collar);

      // Each sail is fixed at 90° around the shaft, then the entire assembly
      // rotates slowly on the horizontal shaft.
      const sail = new THREE.Group();
      sail.position.x = x;
      sail.rotation.x = index * Math.PI / 2;
      rotatingAssembly.add(sail);

      // Main boom.
      addBox(
        0.15,
        6.75,
        0.15,
        materials.darkWood,
        0,
        3.35,
        0,
        sail
      );

      // Lower tip.
      addBox(
        0.18,
        0.22,
        0.18,
        materials.wood,
        0,
        0.08,
        0,
        sail
      );

      // Upper tip.
      addBox(
        0.18,
        0.28,
        0.18,
        materials.wood,
        0,
        6.68,
        0,
        sail
      );

      // Central spar.
      beamBetween(
        [0, 0.25, 0],
        [0, 6.45, 0],
        0.1,
        materials.wood,
        sail
      );

      // Crossbars form the lattice.
      [0.65, 1.7, 2.75, 3.8, 4.85, 5.9].forEach((y) => {
        addBox(
          0.085,
          0.085,
          1.28,
          materials.wood,
          0,
          y,
          0,
          sail
        );
      });

      // Alternating diagonal rods create a diamond lattice.
      for (let i = 0; i < 5; i++) {
        const y0 = 0.75 + i * 1.05;
        const y1 = y0 + 1.05;

        beamBetween(
          [0, y0, -0.64],
          [0, y1, 0.64],
          0.065,
          materials.wood,
          sail
        );
      }

      // Small decorative tip boards.
      beamBetween(
        [0, 6.45, -0.55],
        [0, 6.68, 0],
        0.08,
        materials.wood,
        sail
      );

      beamBetween(
        [0, 6.45, 0.55],
        [0, 6.68, 0],
        0.08,
        materials.wood,
        sail
      );
    });

    // -------------------------------------------------------------------------
    // Direct camera controls: orbit, zoom, and reset
    // -------------------------------------------------------------------------

    const cameraTarget = new THREE.Vector3(0, 4.7, 0);
    const defaultView = {
      theta: 0.72,
      phi: 1.16,
      radius: 16.5
    };

    let theta = defaultView.theta;
    let phi = defaultView.phi;
    let radius = defaultView.radius;
    let dragging = false;
    let pointerX = 0;
    let pointerY = 0;

    function updateCamera() {
      const sinPhi = Math.sin(phi);

      camera.position.set(
        cameraTarget.x + radius * sinPhi * Math.sin(theta),
        cameraTarget.y + radius * Math.cos(phi),
        cameraTarget.z + radius * sinPhi * Math.cos(theta)
      );

      camera.lookAt(cameraTarget);
    }

    function resetCamera() {
      theta = defaultView.theta;
      phi = defaultView.phi;
      radius = defaultView.radius;
      updateCamera();
    }

    const canvas = renderer.domElement;

    canvas.addEventListener("pointerdown", (event) => {
      dragging = true;
      pointerX = event.clientX;
      pointerY = event.clientY;
      canvas.setPointerCapture(event.pointerId);
    });

    canvas.addEventListener("pointermove", (event) => {
      if (!dragging) return;

      const deltaX = event.clientX - pointerX;
      const deltaY = event.clientY - pointerY;

      pointerX = event.clientX;
      pointerY = event.clientY;

      theta -= deltaX * 0.006;
      phi = THREE.MathUtils.clamp(phi - deltaY * 0.005, 0.35, 1.48);
      updateCamera();
    });

    function endDrag(event) {
      dragging = false;
      if (event.pointerId !== undefined && canvas.hasPointerCapture(event.pointerId)) {
        canvas.releasePointerCapture(event.pointerId);
      }
    }

    canvas.addEventListener("pointerup", endDrag);
    canvas.addEventListener("pointercancel", endDrag);

    canvas.addEventListener(
      "wheel",
      (event) => {
        event.preventDefault();
        radius = THREE.MathUtils.clamp(
          radius * Math.exp(event.deltaY * 0.001),
          9,
          28
        );
        updateCamera();
      },
      { passive: false }
    );

    canvas.addEventListener("dblclick", resetCamera);

    window.addEventListener("resize", () => {
      camera.aspect = innerWidth / innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(innerWidth, innerHeight);
      renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
    });

    updateCamera();

    // -------------------------------------------------------------------------
    // Animation
    // -------------------------------------------------------------------------

    const clock = new THREE.Clock();

    function animate() {
      const delta = Math.min(clock.getDelta(), 0.05);

      // Approximately one revolution every 29 seconds.
      rotatingAssembly.rotation.x += delta * 0.22;

      renderer.render(scene, camera);
    }

    renderer.setAnimationLoop(animate);
  </script>
</body>
</html>
```
